  name: String(body.name ?? ""), email: String(body.email ?? ""), phone: String(body.phone ?? ""),
  address: String(body.address ?? ""), city: String(body.city ?? ""), notes: String(body.notes ?? ""),
  status: body.status === "inactive" ? "inactive" as const : "active" as const,
}; }
export async function GET() {
  if (!(await authorized())) return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  try { return NextResponse.json({ data: await getConvexClient().query(api.records.listClients, { secret: getConvexAdminSecret() }) }); }
  catch (error) { console.error("Admin clients fetch error:", error); return NextResponse.json({ message: "Failed to load clients" }, { status: 500 }); }
}
export async function POST(request: Request) {
  if (!(await authorized())) return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  try {
    const payload = fields(await request.json());
    if (!payload.name || !payload.phone) return NextResponse.json({ message: "Missing required fields" }, { status: 400 });
    await getConvexClient().mutation(api.records.createClient, { secret: getConvexAdminSecret(), ...payload });
