import { ConvexError } from "convex/values";
import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { isValidAdminSession } from "@/lib/admin-auth";
import { getConvexAdminSecret, getConvexClient } from "@/lib/convex/server";
import { api } from "@/convex/_generated/api";
import type { Id } from "@/convex/_generated/dataModel";
import { documentPayload } from "@/lib/commercial-documents";

async function authorized() { return isValidAdminSession((await cookies()).get("admin_session")?.value); }
export async function GET(request: Request) {
  if (!(await authorized())) return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  try {
    const params = new URL(request.url).searchParams;
    const id = params.get("id");
    const client = getConvexClient(), secret = getConvexAdminSecret();
    return NextResponse.json({ data: id ? await client.query(api.records.getDocument, { secret, id: id as Id<"commercialDocuments"> }) : await client.query(api.records.listDocuments, { secret, cursor: params.get("cursor") }) });
  } catch (error) { console.error("Document fetch failed", error); return NextResponse.json({ message: "Impossible de charger les documents." }, { status: 500 }); }
}
export async function POST(request: Request) {
  if (!(await authorized())) return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  try {
    const parsed = documentPayload.safeParse(await request.json());
    if (!parsed.success) return NextResponse.json({ message: "V�rifiez le client, la date et les montants." }, { status: 400 });
    const { id, projectId, ...fields } = parsed.data;
    const project = projectId === null
      ? { projectId: null }
      : projectId
        ? { projectId: projectId as Id<"projects"> }
        : {};
    const data = await getConvexClient().mutation(api.records.saveQuote, { secret: getConvexAdminSecret(), ...fields, ...project, ...(id ? { id: id as Id<"commercialDocuments"> } : {}) });
    return NextResponse.json({ data });
  } catch (error) {
    console.error("Document save failed", error);
    const data = error instanceof ConvexError ? error.data : null;
    const code = data && typeof data === "object" && "code" in data ? data.code : null;
    if (code === "DOCUMENT_CHANGED") return NextResponse.json({ message: "Ce devis a chang\u00e9 ailleurs. Rouvrez-le depuis la liste avant de r\u00e9essayer." }, { status: 409 });
    if (code === "QUOTE_NOT_FOUND") return NextResponse.json({ message: "Ce devis est introuvable. Actualisez la liste des documents." }, { status: 404 });
    return NextResponse.json({ message: "Impossible d'enregistrer le devis pour le moment. R\u00e9essayez dans quelques instants." }, { status: 500 });
  }
}
export async function DELETE(request: Request) {
  if (!(await authorized())) return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  try {
    const body = await request.json();
    if (typeof body.id !== "string") return NextResponse.json({ message: "Document invalide." }, { status: 400 });
    await getConvexClient().mutation(api.records.deleteDocument, { secret: getConvexAdminSecret(), id: body.id as Id<"commercialDocuments"> });
    return NextResponse.json({ success: true });
  } catch (error) {
    console.error("Document delete failed", error);
    return NextResponse.json({ message: "Impossible de supprimer ce document." }, { status: 500 });
  }
}
export async function PATCH(request: Request) {
  if (!(await authorized())) return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  try {
    const body = await request.json();
    if (typeof body.id !== "string" || typeof body.date !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(body.date)) return NextResponse.json({ message: "Document ou date invalide." }, { status: 400 });
    const data = await getConvexClient().mutation(api.records.convertQuote, { secret: getConvexAdminSecret(), id: body.id as Id<"commercialDocuments">, date: body.date });
    return NextResponse.json({ data });
  } catch (error) { console.error("Invoice conversion failed", error); return NextResponse.json({ message: "Impossible de convertir ce devis." }, { status: 409 }); }
}


