const PROJECT_STATUSES = ["lead", "design", "production", "installation", "completed", "on_hold", "cancelled"] as const;
const PROJECT_PRIORITIES = ["low", "normal", "high"] as const;

type ProjectStatus = (typeof PROJECT_STATUSES)[number];
type ProjectPriority = (typeof PROJECT_PRIORITIES)[number];

function text(value: unknown) {
  return String(value ?? "");
}

function projectStatus(value: unknown): ProjectStatus {
  return PROJECT_STATUSES.includes(value as ProjectStatus) ? (value as ProjectStatus) : "lead";
}

function projectPriority(value: unknown): ProjectPriority {
  return PROJECT_PRIORITIES.includes(value as ProjectPriority) ? (value as ProjectPriority) : "normal";
}

function budgetCents(value: unknown) {
  const amount = Number(value);
  return Number.isFinite(amount) && amount >= 0 ? Math.round(amount) : 0;
}

function clientId(value: unknown): Id<"clients"> | null | undefined {
  if (value === null || value === undefined || value === "") return value === null ? null : undefined;
  return typeof value === "string" ? (value as Id<"clients">) : undefined;
}

function fields(body: Record<string, unknown>) {
