export function formatMoney(cents = 0) {
  const value = Math.round(cents) / 100;
  const [integer, decimals] = value.toFixed(2).split(".");
  const grouped = integer.replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  return `${grouped},${decimals} MAD`;
