import * as SecureStore from "expo-secure-store";
import { Platform } from "react-native";

const TOKEN_KEY = "faou_admin_token";
const EMAIL_KEY = "faou_admin_email";

function webStorage() {
  if (typeof window === "undefined") return null;
  return window.localStorage;
}

export async function getStoredToken() {
  if (Platform.OS === "web") return webStorage()?.getItem(TOKEN_KEY) ?? null;
  return SecureStore.getItemAsync(TOKEN_KEY);
}

export async function getStoredEmail() {
  if (Platform.OS === "web") return webStorage()?.getItem(EMAIL_KEY) ?? null;
  return SecureStore.getItemAsync(EMAIL_KEY);
}

export async function storeSession(token: string, email: string) {
  if (Platform.OS === "web") {
    webStorage()?.setItem(TOKEN_KEY, token);
    webStorage()?.setItem(EMAIL_KEY, email);
    return;
  }

  await Promise.all([
    SecureStore.setItemAsync(TOKEN_KEY, token),
    SecureStore.setItemAsync(EMAIL_KEY, email),
  ]);
}

export async function clearStoredToken() {
  if (Platform.OS === "web") {
    webStorage()?.removeItem(TOKEN_KEY);
    return;
  }
  await SecureStore.deleteItemAsync(TOKEN_KEY);
}

export async function clearSession() {
  if (Platform.OS === "web") {
    webStorage()?.removeItem(TOKEN_KEY);
    webStorage()?.removeItem(EMAIL_KEY);
    return;
  }

  await Promise.all([
    SecureStore.deleteItemAsync(TOKEN_KEY),
    SecureStore.deleteItemAsync(EMAIL_KEY),
  ]);
}

import { useQueryClient } from "@tanstack/react-query";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import { setUnauthorizedHandler } from "@/api/client";
import { api } from "@/api/endpoints";
import { clearSession, getStoredEmail, getStoredToken, storeSession } from "./storage";

type SessionStatus = "loading" | "authenticated" | "anonymous";

interface SessionValue {
  status: SessionStatus;
  email: string | null;
  isPreview: boolean;
  signIn: (email: string, password: string) => Promise<void>;
  signOut: () => Promise<void>;
}

const DEV_BYPASS = __DEV__ && process.env.EXPO_PUBLIC_DEV_AUTH_BYPASS === "true";

const SessionContext = createContext<SessionValue | null>(null);

export function SessionProvider({ children }: { children: ReactNode }) {
  const queryClient = useQueryClient();
  const [status, setStatus] = useState<SessionStatus>(
    DEV_BYPASS ? "authenticated" : "loading",
  );
  const [email, setEmail] = useState<string | null>(DEV_BYPASS ? "mode aperçu" : null);

  const signOut = useCallback(async () => {
    await clearSession();
    queryClient.clear();
    setEmail(null);
    setStatus("anonymous");
  }, [queryClient]);

  useEffect(() => {
    setUnauthorizedHandler(() => {
      void signOut();
    });
    return () => setUnauthorizedHandler(null);
  }, [signOut]);

  useEffect(() => {
    if (DEV_BYPASS) return;

    let active = true;

    async function hydrate() {
      const [token, storedEmail] = await Promise.all([getStoredToken(), getStoredEmail()]);
      if (!active) return;

      if (token) {
        setEmail(storedEmail);
        setStatus("authenticated");
      } else {
        setStatus("anonymous");
      }
    }

    void hydrate();

    return () => {
      active = false;
    };
  }, []);

  const signIn = useCallback(async (emailInput: string, password: string) => {
    const result = await api.login({ email: emailInput.trim(), password });
    const nextEmail = result.email || emailInput.trim();

    await storeSession(result.token, nextEmail);
    setEmail(nextEmail);
    setStatus("authenticated");
  }, []);

  const value = useMemo<SessionValue>(
    () => ({ status, email, isPreview: DEV_BYPASS, signIn, signOut }),
    [status, email, signIn, signOut],
  );

  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession() {
  const value = useContext(SessionContext);
  if (!value) throw new Error("useSession must be used inside SessionProvider");
  return value;
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
